		      uint8_t *out, uint64_t *out_len) {
    uint32_t clen;
    var_get_u32(in, in+in_len, &clen);
    return use_arith
	? arith_decode(in, in_len, out, out_len)
	: rans_decode(in, in_len, out, out_len);
}

